(() => {
'use strict';
const data = window.SITE_DATA;
const main = document.querySelector('main');
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const arrow = '<span aria-hidden="true">↗</span>';
const price = p => p == null ? '' : `<p class="price">${new Intl.NumberFormat('vi-VN',{style:'currency',currency:'VND'}).format(p)}</p>`;
function shopeeUrl(value) { try { const u = new URL(value); return u.protocol === 'https:' && /(^|\.)(shopee\.vn|shopee\.com|shopee\.ee|shope\.ee)$/.test(u.hostname) ? u.href : null; } catch { return null; } }
function buy(value, extra = '') { const url = shopeeUrl(value); return url ? `<a class="btn ${extra}" href="${esc(url)}" target="_blank" rel="noopener noreferrer">Mua trên Shopee ${arrow}</a>` : `<button class="btn ${extra}" disabled title="Link Shopee đang được bổ sung">Mua trên Shopee ${arrow}</button>`; }
const logo = `<a href="#" class="logo" aria-label="TKaki-Labs — Trang chủ"><img src="${esc(data.logo)}" alt="${esc(data.brand)}" width="180" height="180" loading="lazy"></a>`;
function sizeTable(p) {
 const g = p.sizeGuide;
 const type = g.measurementType === 'body' ? 'cơ thể' : 'quần';
 const columns = g.measurementType === 'body' ? ['Size','Vòng eo','Vòng mông','Chiều cao','Cân nặng'] : ['Size','Lưng quần','Mông quần','Dài quần','Ống quần'];
 const rows = g.rows.length ? g.rows.map(r=>`<tr><th scope="row">${esc(r.size)}</th><td>${esc(r.waist)}</td><td>${esc(r.hip)}</td><td>${esc(r.length)}</td><td>${esc(r.leg)}</td></tr>`).join('') : `<tr><td colspan="5" class="empty-table">Bảng số đo đang được bổ sung.<br>Vui lòng liên hệ shop trước khi chọn size.</td></tr>`;
 return `<div class="table-wrap" tabindex="0" aria-label="Bảng số đo, có thể cuộn ngang trên màn hình nhỏ"><table><caption>Số đo ${type} · Đơn vị: ${esc(g.unit)}</caption><thead><tr>${columns.map(c=>`<th scope="col">${c}</th>`).join('')}</tr></thead><tbody>${rows}</tbody></table></div><p class="table-note">${g.measurementType === 'body' ? 'Đây là số đo cơ thể.' : 'Đây là số đo của quần, không phải số đo cơ thể.'} Thông tin size không thể hiện tình trạng còn hàng.</p>`;
}
function footer() {
 document.querySelector('#footer').innerHTML = `<section id="lien-he" class="contact"><div class="container contact-inner"><div><h2>Liên hệ TKaki-Labs</h2><p class="contact-copy">Cần thêm thông tin về sản phẩm?<br>Bạn có thể liên hệ trực tiếp với shop.</p></div><div class="contact-grid"><div><p class="contact-label">Điện thoại</p><a class="phone" href="tel:${esc(data.contact.phone)}">${esc(data.contact.phoneDisplay)}</a></div><div><p class="contact-label">Địa chỉ</p><p class="address">${esc(data.contact.address)}</p></div></div></div></section><div class="footer"><div class="container footer-inner">${logo}<div class="footer-right"><span>TKaki-Labs · Quần short nam</span>${shopeeUrl(data.links.shopeeShop) ? `<a href="${esc(shopeeUrl(data.links.shopeeShop))}" target="_blank" rel="noopener noreferrer">Ghé shop trên Shopee ↗</a>` : '<button disabled title="Link shop đang được bổ sung">Shopee · Chờ bổ sung link ↗</button>'}</div></div></div>`;
 document.querySelector('#header-buy').innerHTML = buy(data.links.shopeeShop);
}
function home() {
 const p = data.products[0];
 document.title = 'TKaki-Labs — Quần short kaki nam';
 main.innerHTML = `<section class="hero container"><div class="hero-copy"><p class="eyebrow">${esc(data.hero.eyebrow)}</p><h1>${esc(data.hero.title)}</h1><p class="description">${esc(data.hero.description)}</p><div class="hero-actions"><a class="btn" href="#san-pham">Xem sản phẩm <span aria-hidden="true">↓</span></a>${buy(data.links.shopeeShop,'btn-outline')}</div>${!shopeeUrl(data.links.shopeeShop) ? '<p class="link-note">Link Shopee đang được bổ sung.</p>':''}</div><div class="hero-media"><img id="hero-photo" class="hero-photo" src="${esc(p.gallery[0].src)}" alt="${esc(p.gallery[0].alt)}" width="1200" height="1200" fetchpriority="high"><div class="media-caption"><span>TKAKI-LABS / ẢNH SẢN PHẨM</span><div class="arrows"><span id="hero-count" style="align-self:center;margin-right:12px" aria-live="polite">01 / ${String(p.gallery.length).padStart(2,'0')}</span><button class="icon-btn" data-hero-step="-1" aria-label="Xem ảnh trước">←</button><button class="icon-btn" data-hero-step="1" aria-label="Xem ảnh tiếp theo">→</button></div></div></div></section>
<section id="san-pham" class="section"><div class="container"><div class="section-heading"><h2>Bộ sưu tập nhỏ.<br>Cho những ngày thường.</h2><p class="eyebrow">01 — SẢN PHẨM</p></div><div class="collection-grid"><a class="product-image-link" href="#san-pham/${esc(p.id)}" aria-label="Xem chi tiết ${esc(p.name)}"><img src="${esc(p.gallery[p.gallery.length-1].src)}" alt="${esc(p.gallery[p.gallery.length-1].alt)}" width="1200" height="1200" loading="lazy"></a><div class="product-summary"><span class="small-meta">TKaki-Labs / Quần short nam</span><h3>${esc(p.name)}</h3>${p.nameIsTemporary ? '<p class="pending">Tên sản phẩm tạm thời</p>':''}${price(p.price)}<p style="margin-top:22px">Xem những hình ảnh đầu tiên của mẫu quần short kaki từ TKaki-Labs.</p><dl class="product-data"><div><dt>Màu & size</dt><dd>${p.colors.length || p.sizes.length ? esc([...p.colors.map(c=>c.name),...p.sizes].join(' · ')) : 'Đang cập nhật'}</dd></div><div><dt>Thông tin sản phẩm</dt><dd>${p.fabric ? esc(p.fabric) : 'Đang cập nhật'}</dd></div></dl><a class="btn btn-outline" href="#san-pham/${esc(p.id)}">Xem chi tiết <span aria-hidden="true">→</span></a></div></div></div></section>
<section id="bang-size" class="section"><div class="container size-layout"><div class="size-intro"><p class="eyebrow">02 — CHỌN SIZE</p><h2>Chọn size từ số đo.</h2><p>Đối chiếu số đo trước khi chọn quần. Bảng size của mẫu sản phẩm sẽ được cập nhật tại đây.</p><a class="text-link" href="tel:${esc(data.contact.phone)}">Hỏi shop về size ${arrow}</a></div><div>${sizeTable(p)}</div></div></section>
<section id="ve-tkaki" class="about"><div class="container about-inner"><p class="eyebrow">03 — VỀ TKAKI-LABS</p><div><h2>${esc(data.about.title)}</h2><p>${esc(data.about.description)}</p><p class="about-note">${esc(data.about.note)}</p></div></div></section>
<section class="section"><div class="container faq-layout"><div><p class="eyebrow">04 — THÔNG TIN HỮU ÍCH</p><h2>Bạn muốn biết thêm?</h2></div><div>${data.faq.map(f=>`<details><summary>${esc(f.q)}</summary><p>${esc(f.a)}</p></details>`).join('')}</div></div></section>`;
 let idx=0;
 main.querySelectorAll('[data-hero-step]').forEach(b=>b.addEventListener('click',()=>{idx=(idx+Number(b.dataset.heroStep)+p.gallery.length)%p.gallery.length;const photo=document.querySelector('#hero-photo');photo.src=p.gallery[idx].src;photo.alt=p.gallery[idx].alt;document.querySelector('#hero-count').textContent=`${String(idx+1).padStart(2,'0')} / ${String(p.gallery.length).padStart(2,'0')}`;}));
}
function detail(p) {
 document.title = `${p.name} — TKaki-Labs`;
 main.innerHTML=`<article class="container detail"><div class="breadcrumb"><a href="#">Trang chủ</a><span aria-hidden="true">/</span><a href="#san-pham">Sản phẩm</a><span aria-hidden="true">/</span><span>${esc(p.name)}</span></div><div class="detail-grid"><div><button class="gallery-main" aria-label="Phóng lớn ảnh sản phẩm"><img id="detail-image" src="${esc(p.gallery[0].src)}" alt="${esc(p.gallery[0].alt)}" width="1200" height="1200"><span class="expand-label">Phóng lớn ↗</span></button><div class="gallery-thumbs" role="group" aria-label="Chọn ảnh sản phẩm">${p.gallery.map((im,i)=>`<button class="thumb" data-image="${i}" aria-label="Xem ảnh ${i+1}" aria-pressed="${i===0}"><img src="${esc(im.thumb)}" alt="Ảnh ${i+1}" width="360" height="360"></button>`).join('')}</div><p class="gallery-note">Hình ảnh do TKaki-Labs cung cấp. Màu đang bán sẽ được xác nhận sau.</p></div><div class="detail-copy"><p class="eyebrow">TKAKI-LABS / QUẦN SHORT NAM</p><h1>${esc(p.name)}</h1>${p.nameIsTemporary?'<p class="pending">Tên sản phẩm tạm thời</p>':''}${price(p.price)}<p class="detail-desc">${p.description ? esc(p.description) : 'Thông tin chi tiết của mẫu quần này đang được bổ sung. Bạn có thể xem ảnh hoặc liên hệ shop để hỏi thêm.'}</p><dl class="spec-list"><div class="spec-row"><dt>Chất liệu</dt><dd>${esc(p.fabric || 'Đang cập nhật')}</dd></div><div class="spec-row"><dt>Phom quần</dt><dd>${esc(p.fit || 'Đang cập nhật')}</dd></div><div class="spec-row"><dt>Màu đang bán</dt><dd>${p.colors.length?esc(p.colors.map(c=>c.name).join(' · ')):'Chưa có thông tin'}</dd></div><div class="spec-row"><dt>Size</dt><dd>${p.sizes.length?esc(p.sizes.join(' · ')):'Đang cập nhật'}</dd></div></dl>${p.colors.length?`<div class="variant-buttons" role="group" aria-label="Chọn ảnh theo màu">${p.colors.map((c,i)=>`<button class="variant" data-color="${i}" aria-pressed="false">${esc(c.name)}</button>`).join('')}</div>`:''}<a class="text-link size-link" href="#san-pham/${esc(p.id)}/bang-size">Xem bảng size <span aria-hidden="true">↓</span></a>${buy(p.shopeeUrl)}<p class="link-note">${shopeeUrl(p.shopeeUrl)?'Chọn phân loại và đặt mua tại Shopee.':'Link sản phẩm Shopee đang được bổ sung.'}</p><div class="detail-blocks"><details><summary>Hướng dẫn bảo quản</summary><p>${esc(p.care || 'Hướng dẫn bảo quản cụ thể đang được bổ sung.')}</p></details><details><summary>Thông tin mua hàng</summary><p>Việc đặt mua sẽ được thực hiện trên Shopee. ${shopeeUrl(p.shopeeUrl)?'Xem thông tin giao hàng và chính sách áp dụng tại trang sản phẩm trước khi mua.':'Vui lòng chờ link sản phẩm hoặc gọi shop để hỏi thêm.'}</p></details></div><a class="text-link" href="tel:${esc(data.contact.phone)}">Gọi shop: ${esc(data.contact.phoneDisplay)} ${arrow}</a></div></div><section id="detail-size" class="detail-size"><p class="eyebrow">HƯỚNG DẪN CHỌN SIZE</p><h2>Bảng số đo sản phẩm</h2>${sizeTable(p)}</section></article>`;
 let index=0;
 function choose(i){index=i;const im=p.gallery[i];const el=document.querySelector('#detail-image');el.src=im.src;el.alt=im.alt;main.querySelectorAll('[data-image]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.image)===i)));}
 main.querySelectorAll('[data-image]').forEach(b=>b.addEventListener('click',()=>choose(Number(b.dataset.image))));
 main.querySelectorAll('[data-color]').forEach(b=>b.addEventListener('click',()=>{const c=p.colors[Number(b.dataset.color)];if(Number.isInteger(c.imageIndex)&&p.gallery[c.imageIndex])choose(c.imageIndex);main.querySelectorAll('[data-color]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));}));
 main.querySelector('.gallery-main').addEventListener('click',()=>{const img=document.querySelector('#zoom-image');img.src=p.gallery[index].src;img.alt=p.gallery[index].alt;document.querySelector('#zoom-label').textContent=`Ảnh sản phẩm ${index+1} / ${p.gallery.length}`;document.querySelector('#image-dialog').showModal();});
}
let currentView='';
function route(){
 document.querySelector('#mobile-nav').hidden=true;
 document.querySelector('.menu-toggle').setAttribute('aria-expanded','false');
 document.querySelector('.menu-toggle').setAttribute('aria-label','Mở menu');
 const hash=decodeURIComponent(location.hash.slice(1));
 const parts=hash.split('/');
 const p=parts[0]==='san-pham'&&parts[1]?data.products.find(x=>x.id===parts[1]):null;
 const next=p?'detail:'+p.id:'home';
 if(currentView!==next){p?detail(p):home();currentView=next;window.scrollTo(0,0);}
 if(p&&parts[2]==='bang-size')document.querySelector('#detail-size').scrollIntoView();
 else if(!p&&hash){const el=document.getElementById(hash);if(el)el.scrollIntoView();}
 else if(!hash)window.scrollTo(0,0);
 
}
footer();route();window.addEventListener('hashchange',route);
const toggle=document.querySelector('.menu-toggle');
document.querySelectorAll('#mobile-nav a').forEach(a=>a.addEventListener('click',()=>{document.querySelector('#mobile-nav').hidden=true;toggle.setAttribute('aria-expanded','false');toggle.setAttribute('aria-label','Mở menu');}));toggle.addEventListener('click',()=>{const nav=document.querySelector('#mobile-nav');nav.hidden=!nav.hidden;toggle.setAttribute('aria-expanded',String(!nav.hidden));toggle.setAttribute('aria-label',nav.hidden?'Mở menu':'Đóng menu');});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!document.querySelector('#mobile-nav').hidden){document.querySelector('#mobile-nav').hidden=true;toggle.setAttribute('aria-expanded','false');toggle.setAttribute('aria-label','Mở menu');toggle.focus();}});
const dialog=document.querySelector('#image-dialog');document.querySelector('.zoom-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
})();
